SELECT ua.id, ua.user_id AS userId, u.username, ua.action, ua.description, ua.ip_address AS ipAddress, ua.user_agent AS userAgent, ua.details, ua.result, ua.created_at AS createdAt FROM user_activity ua LEFT JOIN "user" u ON ua.user_id = u.id
ua.user_id = #{userId}
AND ua.action = #{params.action}
AND ua.created_at >= #{params.fromDate}
AND ua.created_at <= #{params.toDate}
ORDER BY ua.created_at DESC

SELECT COUNT(*)
FROM user_activity ua

    ua.user_id = #{userId}

        AND ua.action = #{params.action}


        AND ua.created_at >= #{params.fromDate}


        AND ua.created_at <= #{params.toDate}
